 update(dt){if(this.settings.opponent!=='local'&&this.state.turn===1&&!this.done){this.cpuDelay=(this.cpuDelay||0)+dt;if(this.cpuDelay>.8){this.cpuDelay=0;const moves=legalMoves(this.state);moves.sort((a,b)=>{const value=i=>{const n=moveOware(this.state,i);return n.scores[1]-this.state.scores[1]+n.pits.slice(6).filter(n=>n>0).length*.05;};return value(b)-value(a);});this.choose(moves[0],true);}}}
