 update(dt){if(this.settings.opponent!=='local'&&this.state.turn===1&&!this.done){this.cpuDelay=(this.cpuDelay||0)+dt;if(this.cpuDelay>.65){this.cpuDelay=0;const moves=dameMoves(this.state);moves.sort((a,b)=>Number(b.capture!==null)-Number(a.capture!==null)+(Math.random()-.5)*.1);const move=moves[0];if(move){this.selected=move.from;this.choose(move.to,true);}}}}
