 position(p,i){const n=this.state.tokens[p][i];if(n<0)return {x:(p?3:-3)+(i%2)*.85,z:(p?-3:3)+Math.floor(i/2)*.85};if(n>=52)return {x:0,z:(p?-1:1)*(57-n)*.76};const [c,r]=TRACK[ludoCell(p,n)];const offset=(i-1.5)*.09;return{x:(c-7)*.76+offset,z:(r-7)*.76+offset};}
