 choose(i,automatic=false){if(this.settings.opponent!=='local'&&this.state.turn===1&&!automatic)return;const n=moveLudo(this.state,i);if(n===this.state)return;this.state=n;this.ui.sound('stone');if(n.over)return this.finish(`PLAYER ${n.winner+1} WINS`,'All four tokens made it home!');this.note('Player '+(n.turn+1)+', roll the dice.');this.draw();}
