 select(i){if(!Number.isInteger(i)||i<0||i>=this.counterCount)return;this.selected=i;const a=this.caps[this.turn][i];this.capVel=a.userData.velocity;this.aim=Math.atan2(this.b.position.z-a.position.z,this.b.position.x-a.position.x);}
