 hit({id,point}){if(this.equipment&&point)point=this.equipment.worldToLocal(point.clone());if(this.settings.opponent!=='local'&&this.turn===1)return;if(this.phase!=='aim')return;if(id?.p===this.turn)this.select(id.i);else if(point){const a=this.caps[this.turn][this.selected];this.aim=Math.atan2(point.z-a.position.z,point.x-a.position.x);}}
