  const choices=this.caps[1].map((p,i)=>{const approach=this.b.position.clone().sub(p.position).normalize(),alignment=approach.dot(direction);return {p,i,alignment,cost:distance(p,contact)+(1-alignment)*10};}).sort((a,b)=>a.cost-b.cost),choice=choices[0];this.select(choice.i);
  const target=choice.alignment>.35?contact:{x:Math.min(6.5,this.b.position.x+2),z:THREE.MathUtils.clamp(this.b.position.z+(choice.p.position.z>this.b.position.z?1.5:-1.5),-3.5,3.5)};
